<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config/product_step12.php';
if(empty($_SESSION['product_cost_csrf']))$_SESSION['product_cost_csrf']=bin2hex(random_bytes(24));
$csrf=(string)$_SESSION['product_cost_csrf'];$error=null;$success=null;$rows=[];$costs=[];$q=trim((string)($_GET['q']??''));
try{
    $pdo=business_db();product_step12_ensure($pdo);$ctx=product_step12_context($pdo);$orgId=(int)$ctx['organization_id'];
    if($_SERVER['REQUEST_METHOD']==='POST'){
        if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');
        $productId=(int)($_POST['product_id']??0);$date=trim((string)($_POST['effective_from']??''));$cost=(float)($_POST['unit_cost']??0);$source=trim((string)($_POST['source_reference']??''));$notes=trim((string)($_POST['notes']??''));
        $costId=product_step12_add_cost($pdo,$productId,$date,$cost,$source,$notes);$success='Explicit cost version #'.$costId.' saved and affected active sales recalculated.';
    }
    $rows=product_step11_catalog_rows($pdo,$orgId,$q,'ALL');
    $stmt=$pdo->prepare("SELECT cv.*,p.product_name,p.sku FROM product_cost_versions cv JOIN products p ON p.id=cv.product_id AND p.organization_id=cv.organization_id WHERE cv.organization_id=? AND cv.status='active' ORDER BY cv.effective_from DESC,cv.id DESC LIMIT 150");$stmt->execute([$orgId]);$costs=$stmt->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
function pcc_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?>
